<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/csrf.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/attendance.php';
$current=tuman_require_role('TEACHER');$db=tuman_database();$error=null;$students=array_filter(tuman_teacher_students($db,$current['id']),fn($s)=>$s['assignment_status']==='ACTIVE');$rules=array_filter(tuman_teacher_billing_rules($db,$current['id']),fn($r)=>$r['status']==='ACTIVE'&&$r['billing_mode']==='HOURLY');$batches=tuman_teacher_batches($db,$current['id']);$batchRules=[];foreach($batches as $batch){foreach(tuman_batch_billing_rules($db,$current['id'],(int)$batch['id']) as $rule){if($rule['status']==='ACTIVE')$batchRules[]=$rule+['batch_name'=>$batch['batch_name']];}}$v=['assignment_id'=>'','session_date'=>gmdate('Y-m-d'),'status'=>'PRESENT','start_time'=>'','end_time'=>'','billing_rule_id'=>'','batch_id'=>'','batch_billing_rule_id'=>'','remarks'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){foreach($v as $k=>$x)$v[$k]=trim((string)($_POST[$k]??''));try{if(!tuman_csrf_is_valid($_POST['csrf_token']??null))throw new InvalidArgumentException('Your request could not be verified.');$assignment=filter_var($v['assignment_id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$assignment)throw new InvalidArgumentException('Choose a student.');tuman_create_attendance($db,$current['id'],(int)$assignment,$v);header('Location: /Tuman/teacher/attendance.php?created=1');exit;}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log($e->getMessage());$error='Unable to save attendance right now.';}}tuman_teacher_page_start('Record attendance');
?>
<h1>Record attendance</h1><p>Select a batch for a batch class; leave it blank for an individual lesson.</p><?php if($error):?><p role="alert"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(tuman_csrf_token(),ENT_QUOTES,'UTF-8')?>"><p><label>Student <select name="assignment_id" required><option value="">Choose student</option><?php foreach($students as $s):?><option value="<?=(int)$s['assignment_id']?>"<?=$v['assignment_id']==$s['assignment_id']?' selected':''?>><?=htmlspecialchars(trim($s['first_name'].' '.($s['last_name']??'')),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><label>Class type / batch <select name="batch_id"><option value="">Individual class</option><?php foreach($batches as $batch):if($batch['status']==='ACTIVE'):?><option value="<?=(int)$batch['id']?>"<?=$v['batch_id']==$batch['id']?' selected':''?>><?=htmlspecialchars($batch['batch_name'],ENT_QUOTES,'UTF-8')?></option><?php endif;endforeach;?></select></label></p><p><label>Session date <input type="date" name="session_date" required value="<?=htmlspecialchars($v['session_date'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Status <select name="status"><?php foreach(TUMAN_ATTENDANCE_STATUSES as $s):?><option value="<?=$s?>"<?=$s===$v['status']?' selected':''?>><?=$s?></option><?php endforeach;?></select></label></p><p><label>Start time <input type="time" name="start_time" value="<?=htmlspecialchars($v['start_time'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>End time <input type="time" name="end_time" value="<?=htmlspecialchars($v['end_time'],ENT_QUOTES,'UTF-8')?>"></label></p><p><label>Hourly rule <select name="billing_rule_id"><option value="">Automatic / no extra hourly charge</option><?php foreach($rules as $r):?><option value="<?=(int)$r['id']?>"<?=$v['billing_rule_id']==$r['id']?' selected':''?>><?=htmlspecialchars(($r['rule_name']??('Rule #'.$r['id'])).' — '.tuman_billing_rate_label($r['rate'],'HOURLY',$r['currency_code']),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label></p><p><label>Remarks <textarea name="remarks" maxlength="500"><?=htmlspecialchars($v['remarks'],ENT_QUOTES,'UTF-8')?></textarea></label></p><p><button>Save attendance</button> <a href="/Tuman/teacher/attendance.php">Cancel</a></p></form>
<?php tuman_teacher_page_end();?>
